/* V8.54.3 — Team Wars Ranked Queue + Same-Tag Lock */
const teamWarsState={loading:false,error:'',team:null,membership:null,members:[],memberProfiles:new Map(),wars:[],allTeams:[],standings:[],seasonStandings:[],seasons:[],selectedSeason:null,seasonEntries:[],schedule:[],playoffs:[],awards:[],applications:[],freeAgents:[],rankedQueue:null,rankedMatch:null,rankedSeason:null,rankedLadder:[],rankedHistory:[],rankedContributors:[],rankedArchive:[],rankedArchiveLadder:[],rankedArchiveSeason:null,rankedDisputes:[],rankedStaff:false,rankedDisputeEvents:[],rankedEvidence:[],rankedEvidenceUrls:new Map(),rankedPlayerProfiles:new Map(),selectedWar:null,lineups:[],matches:[],badges:[],achievementCatalog:[],profileSearchResults:[],publicProfile:null,publicTeam:null};
const teamWarsUi={tab:'overview'};
function setTeamWarsTab(tab){teamWarsUi.tab=tab||'overview';teamWarsPage(false)}
let rankedRoomPollTimer=null;
function stopRankedRoomPolling(){if(rankedRoomPollTimer){clearInterval(rankedRoomPollTimer);rankedRoomPollTimer=null}}
function startRankedRoomPolling(){stopRankedRoomPolling();if(!ptSigned())return;rankedRoomPollTimer=setInterval(async()=>{if(teamWarsUi.tab!=='ranked'||document.hidden)return;const m=teamWarsState.rankedMatch,q=teamWarsState.rankedQueue;if(!m&&!q)return;try{await loadProfileTeamData(false);if(teamWarsUi.tab==='ranked')teamWarsPage(false)}catch{}},15000)}
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&teamWarsUi.tab==='ranked')refreshRankedLifecycle?.()});

function openCloudAccountFromCompetitive(){
 try{
  state.page='account';
  if(typeof accountPage==='function'){accountPage();nav?.();return}
  if(typeof goPage==='function'){goPage('account');return}
 }catch(e){console.error('Open Account failed',e)}
 const root=document.getElementById('app');
 if(root)root.innerHTML='<div class="panel"><h2>Account</h2><p class="muted">Account screen could not open. Refresh the page and try again.</p></div>';
}
window.openCloudAccountFromCompetitive=openCloudAccountFromCompetitive;

function ptClient(){return window.getPPCCloudClient?.()||window.cloudClient||null}
function ptSession(){return window.getPPCCloudSession?.()||window.cloudSession||null}
function ptSigned(){return !!ptClient()&&!!ptSession()?.user}
function fmtWhen(v){if(!v)return 'Not scheduled';try{return new Date(v).toLocaleString()}catch{return String(v)}}
function shortId(v){return String(v||'').slice(0,8)}
function safeUrl(v){const s=String(v||'').trim();return /^https?:\/\//i.test(s)?s:''}
function initials(p){const n=String(p?.display_name||p?.username||'P').trim();return n.slice(0,1).toUpperCase()||'P'}
function avatarHtml(p,cls='identityAvatar'){const u=safeUrl(p?.avatar_url);return u?`<div class="${cls} imageAvatar" style="background-image:url('${esc(u)}')"></div>`:`<div class="${cls}">${esc(initials(p))}</div>`}
function logoHtml(t,cls='teamLogo'){const u=safeUrl(t?.logo_url);return u?`<div class="${cls} imageAvatar" style="background-image:url('${esc(u)}')"></div>`:`<div class="${cls}">${esc(String(t?.tag||'T').slice(0,2))}</div>`}
function userDeckChoices(){
 const mine=(state.decks||[]).filter(d=>{try{return typeof deckCount==='function'?deckCount(d)>0:(Array.isArray(d.cards)?d.cards.length:Object.keys(d.cards||{}).length)}catch{return false}}).map(d=>({id:'user:'+d.id,name:d.name||'Saved Deck',source:'user',cards:d.cards,energy:d.energy||d.energyTypes||[]}));
 let meta=[];try{meta=(window.ArchetypeService?.all?.()||window.ArchetypeService?.getAll?.()||[]).filter(a=>Array.isArray(a.sampleDeck)&&a.sampleDeck.length).map(a=>({id:'meta:'+a.id,name:a.name,source:'meta',cards:a.sampleDeck,energy:a.energy||[]}))}catch{}
 return [...mine,...meta];
}
function deckSnapById(id){const d=userDeckChoices().find(x=>x.id===id);return d?{id:d.id,name:d.name,source:d.source,cards:d.cards,energy:d.energy}:{} }
function deckOptions(sel=''){return `<option value="">Choose deck…</option>${userDeckChoices().map(d=>`<option value="${esc(d.id)}" ${d.id===sel?'selected':''}>${esc(d.source==='meta'?'META • '+d.name:d.name)}</option>`).join('')}`}
function memberProfile(uid){return teamWarsState.memberProfiles.get(uid)||{display_name:uid===ptSession()?.user?.id?'You':'Player',username:'',avatar_url:''}}
function memberLabel(uid){const p=memberProfile(uid);return p.display_name||p.username||shortId(uid)}
function badgeCards(list){return (list||[]).length?`<div class="badgeShelf">${list.map(b=>`<article class="achievementBadge ${esc(b.tier||'common')}"><span>${esc(b.icon||'◆')}</span><div><div class="badgeTitleRow"><strong>${esc(b.label||b.badge_key||'Badge')}</strong><em>${esc(String(b.tier||'common').toUpperCase())}</em></div><small>${esc(b.description||'')}</small>${b.earned_at?`<small class="badgeEarned">Earned ${esc(new Date(b.earned_at).toLocaleDateString())}</small>`:''}</div></article>`).join('')}</div>`:`<div class="identityEmpty"><strong>No achievements yet</strong><span>Battle, join a team, and complete Team Wars to unlock achievements.</span></div>`}
function featuredBadgeCards(profile,badges){const keys=Array.isArray(profile?.featured_badges)?profile.featured_badges.map(String):[];const map=new Map((badges||[]).map(b=>[String(b.badge_key||b.key),b]));const picked=keys.map(k=>map.get(k)).filter(Boolean).slice(0,4);return badgeCards(picked.length?picked:(badges||[]).slice(0,4))}
function achievementCollectionHtml(){const earned=new Map((teamWarsState.badges||[]).map(b=>[String(b.badge_key||b.key),b]));const catalog=teamWarsState.achievementCatalog||[];if(!catalog.length)return badgeCards(teamWarsState.badges);return `<div class="achievementCollection">${catalog.map(a=>{const got=earned.get(String(a.badge_key));return got?`<article class="achievementBadge ${esc(got.tier||a.tier||'common')}"><span>${esc(got.icon||a.icon||'◆')}</span><div><div class="badgeTitleRow"><strong>${esc(got.label||a.label)}</strong><em>${esc(String(got.tier||a.tier||'common').toUpperCase())}</em></div><small>${esc(got.description||a.description||'')}</small><small class="badgeEarned">Earned ${esc(new Date(got.earned_at).toLocaleDateString())}</small></div></article>`:`<article class="achievementBadge locked ${esc(a.tier||'common')}"><span>?</span><div><div class="badgeTitleRow"><strong>${esc(a.label)}</strong><em>${esc(String(a.tier||'common').toUpperCase())}</em></div><small>${esc(a.description||'')}</small><small class="badgeEarned">Locked</small></div></article>`}).join('')}</div>`}
function profileSearchResultsHtml(rows){if(!rows?.length)return `<div class="profileSearchEmpty muted">Search by username or display name to find public players.</div>`;return `<div class="profileSearchGrid">${rows.map(r=>`<button class="profileSearchCard" onclick="openPublicProfileByPublicId('${esc(r.public_id)}')">${avatarHtml(r,'profileSearchAvatar')}<div><strong>${esc(r.display_name||r.username)}</strong><small>${r.username?'@'+esc(r.username):'Public player'}${r.team_tag?` • [${esc(r.team_tag)}] ${esc(r.team_name||'')}`:''}</small><span>${esc(r.current_rank||'Rank not shared')}${Number.isFinite(r.current_rp)?` • ${r.current_rp} RP`:''}</span></div><div class="profileSearchStats"><b>${Number(r.wins||0)}</b><small>Wins</small><b>${Number(r.badge_count||0)}</b><small>Badges</small></div></button>`).join('')}</div>`}
function profileSearchPanel(){return `<section class="panel profileSearchPanel"><div class="between"><div><span class="eyebrow">PLAYER SEARCH</span><h2>Find a competitor</h2></div><span class="pill">Public profiles</span></div><div class="profileSearchBar"><input id="profileSearchInput" placeholder="Search username or display name" onkeydown="if(event.key==='Enter'){event.preventDefault();searchPublicProfiles()}"><button onclick="searchPublicProfiles()">Search</button></div><div id="profileSearchResults">${profileSearchResultsHtml(teamWarsState.profileSearchResults)}</div></section>`}
async function searchPublicProfiles(){const q=(document.getElementById('profileSearchInput')?.value||'').trim();const c=await ensurePublicClient();if(!c)return ppcNotice('Player search is temporarily unavailable.');const box=document.getElementById('profileSearchResults');if(box)box.innerHTML='<div class="profileSearchEmpty muted">Searching…</div>';const {data,error}=await c.rpc('search_public_profiles',{p_query:q,p_limit:24});if(error){if(box)box.innerHTML=`<div class="dangerBox">${esc(error.message)}</div>`;return}teamWarsState.profileSearchResults=data||[];if(box)box.innerHTML=profileSearchResultsHtml(teamWarsState.profileSearchResults)}


async function refreshCompetitiveIdentity(){if(!ptSigned())return;try{await ptClient().rpc('refresh_my_public_identity');const {data}=await ptClient().from('profiles').select('*').eq('id',ptSession().user.id).maybeSingle();if(data)cloudProfile=data}catch(e){console.warn('identity refresh',e)}}
async function loadProfileTeamData(force=false){
 if(!ptSigned())return;
 if(teamWarsState.loading&&!force)return;
 teamWarsState.loading=true;teamWarsState.error='';
 try{
  const c=ptClient(),uid=ptSession().user.id;
  try{await c.rpc('cleanup_team_ranked_lifecycle')}catch(e){console.warn('ranked lifecycle cleanup',e)}
  if(force)await refreshCompetitiveIdentity();
  const [{data:mem,error:me},{data:teams,error:te},{data:stands,error:se},{data:seasonStands},{data:seasons},{data:badges},{data:catalog}]=await Promise.all([
   c.from('team_members').select('team_id,role,status,joined_at').eq('user_id',uid).limit(1).maybeSingle(),
   c.from('teams').select('id,name,tag,logo_url,description,captain_user_id,is_public,max_members,rating_points,ranked_wins,ranked_losses,created_at,updated_at').order('name').limit(100),
   c.rpc('get_team_war_standings'),c.rpc('get_team_season_standings',{p_season_id:null}),
   c.from('team_seasons').select('*').order('starts_at',{ascending:false}).limit(12),
   c.from('profile_badges').select('*').eq('user_id',uid).order('earned_at',{ascending:false}),
   c.from('profile_achievement_catalog').select('*').eq('hidden',false).order('sort_order')
  ]);
  if(me)throw me;if(te)throw te;if(se)console.warn(se);
  teamWarsState.membership=mem||null;teamWarsState.allTeams=teams||[];teamWarsState.standings=stands||[];teamWarsState.seasonStandings=seasonStands||[];teamWarsState.seasons=seasons||[];teamWarsState.badges=badges||[];teamWarsState.achievementCatalog=catalog||[];
  teamWarsState.team=mem?(teams||[]).find(t=>t.id===mem.team_id)||null:null;
  if(teamWarsState.team){
   const tid=teamWarsState.team.id;
   const [{data:members},{data:wars}]=await Promise.all([
    c.from('team_members').select('team_id,user_id,role,status,joined_at').eq('team_id',tid).order('joined_at'),
    c.from('team_wars').select('*').or(`home_team_id.eq.${tid},away_team_id.eq.${tid}`).order('created_at',{ascending:false}).limit(30)
   ]);
   teamWarsState.members=members||[];teamWarsState.wars=wars||[];
   const ids=teamWarsState.members.map(m=>m.user_id);teamWarsState.memberProfiles=new Map();
   if(ids.length){const {data:profiles}=await c.from('profiles').select('id,display_name,username,avatar_url,current_rank,current_rp').in('id',ids);for(const p of profiles||[])teamWarsState.memberProfiles.set(p.id,p)}
  }else{teamWarsState.members=[];teamWarsState.wars=[];teamWarsState.memberProfiles=new Map()}
  const [{data:rq},{data:rankedSeason},{data:rankedLadder,error:rankedLadderError}]=await Promise.all([
   c.from('team_ranked_queue').select('*').eq('user_id',uid).maybeSingle(),
   c.rpc('get_current_team_ranked_season'),
   c.rpc('get_team_ranked_ladder',{p_limit:100})
  ]);
  teamWarsState.rankedQueue=rq||null;teamWarsState.rankedSeason=rankedSeason||null;teamWarsState.rankedLadder=rankedLadder||[];if(rankedLadderError)console.warn(rankedLadderError);
  teamWarsState.rankedMatch=null;teamWarsState.rankedPlayerProfiles=new Map();
  if(rq?.matched_match_id){const {data:rm}=await c.from('team_ranked_matches').select('*').eq('id',rq.matched_match_id).maybeSingle();teamWarsState.rankedMatch=rm||null}
  // V8.60.3 reconnect recovery: an active match must survive queue-row cleanup, refreshes, and device changes.
  if(!teamWarsState.rankedMatch){const {data:activeMatches,error:activeMatchError}=await c.from('team_ranked_matches').select('*').or(`player_a_id.eq.${uid},player_b_id.eq.${uid}`).in('status',['matched','reported','disputed']).order('created_at',{ascending:false}).limit(1);if(!activeMatchError&&activeMatches?.length)teamWarsState.rankedMatch=activeMatches[0]}
  if(teamWarsState.rankedMatch){const playerIds=[teamWarsState.rankedMatch.player_a_id,teamWarsState.rankedMatch.player_b_id].filter(Boolean);if(playerIds.length){const {data:rankedProfiles}=await c.from('profiles').select('id,display_name,username,avatar_url').in('id',playerIds);for(const p of rankedProfiles||[])teamWarsState.rankedPlayerProfiles.set(p.id,p)}}
  teamWarsState.rankedHistory=[];teamWarsState.rankedContributors=[];teamWarsState.rankedArchive=[];teamWarsState.rankedDisputes=[];teamWarsState.rankedDisputeEvents=[];teamWarsState.rankedEvidence=[];teamWarsState.rankedEvidenceUrls=new Map();teamWarsState.rankedStaff=false;
  const [staffCheck,archive]=await Promise.all([c.rpc('is_team_ranked_staff'),c.rpc('get_team_ranked_season_archive',{p_limit:24})]);
  if(!staffCheck.error)teamWarsState.rankedStaff=!!staffCheck.data;if(!archive.error)teamWarsState.rankedArchive=archive.data||[];
  if(teamWarsState.team){const [hist,contrib]=await Promise.all([c.rpc('get_team_ranked_history',{p_team_id:teamWarsState.team.id,p_limit:30}),c.rpc('get_team_ranked_contributors',{p_team_id:teamWarsState.team.id})]);if(!hist.error)teamWarsState.rankedHistory=hist.data||[];if(!contrib.error)teamWarsState.rankedContributors=contrib.data||[];}
  let disputeQuery=c.from('team_ranked_disputes').select('*').order('created_at',{ascending:false}).limit(teamWarsState.rankedStaff?100:30);
  if(!teamWarsState.rankedStaff&&teamWarsState.team)disputeQuery=disputeQuery.or(`team_a_id.eq.${teamWarsState.team.id},team_b_id.eq.${teamWarsState.team.id}`);
  if(teamWarsState.rankedStaff||teamWarsState.team){const disputes=await disputeQuery;if(!disputes.error)teamWarsState.rankedDisputes=disputes.data||[];}
  const disputeIds=teamWarsState.rankedDisputes.map(x=>x.id);if(disputeIds.length){const [events,evidence]=await Promise.all([c.from('team_ranked_dispute_events').select('*').in('dispute_id',disputeIds).order('created_at',{ascending:false}).limit(200),c.from('team_ranked_dispute_evidence').select('*').in('dispute_id',disputeIds).order('created_at',{ascending:false}).limit(300)]);if(!events.error)teamWarsState.rankedDisputeEvents=events.data||[];if(!evidence.error){teamWarsState.rankedEvidence=evidence.data||[];for(const ev of teamWarsState.rankedEvidence){try{const signed=await c.storage.from('team-ranked-evidence').createSignedUrl(ev.storage_path,900);if(!signed.error&&signed.data?.signedUrl)teamWarsState.rankedEvidenceUrls.set(ev.id,signed.data.signedUrl)}catch(e){console.warn('evidence url',e)}}}}
  const [{data:apps},{data:fa},{data:entries},{data:schedule},{data:playoffs},{data:awards}]=await Promise.all([
   c.from('team_applications').select('*').order('created_at',{ascending:false}).limit(100),
   c.from('team_free_agents').select('*').eq('looking',true).order('updated_at',{ascending:false}).limit(100),
   c.from('team_season_entries').select('*').limit(500),
   c.from('team_season_schedule').select('*').order('round_no').order('scheduled_at').limit(500),
   c.from('team_playoff_matches').select('*').order('bracket_round').order('match_no').limit(200),
   c.from('team_season_awards').select('*').order('created_at',{ascending:false}).limit(100)
  ]);
  teamWarsState.applications=apps||[];teamWarsState.freeAgents=fa||[];teamWarsState.seasonEntries=entries||[];teamWarsState.schedule=schedule||[];teamWarsState.playoffs=playoffs||[];teamWarsState.awards=awards||[];
  teamWarsState.selectedSeason=(teamWarsState.selectedSeason&&teamWarsState.seasons.find(x=>x.id===teamWarsState.selectedSeason.id))||teamWarsState.seasons.find(x=>x.status==='active')||teamWarsState.seasons[0]||null;
  if(teamWarsState.selectedSeason){const {data:ss,error:sse}=await c.rpc('get_team_season_standings',{p_season_id:teamWarsState.selectedSeason.id});if(!sse)teamWarsState.seasonStandings=ss||[]}
 }catch(e){teamWarsState.error=e?.message||String(e)}finally{teamWarsState.loading=false}
}
async function profileSave(){
 if(!ptSigned())return ppcNotice('Sign in to save your profile.');
 const uid=ptSession().user.id,c=ptClient(),publicProfile=!!document.getElementById('pfPublic')?.checked;
 const selectedShowcase=[...document.getElementById('pfShowcase')?.selectedOptions||[]].slice(0,3).map(o=>String(o.value));const selectedBadges=[...document.getElementById('pfFeaturedBadges')?.selectedOptions||[]].slice(0,4).map(o=>String(o.value));
 const showcaseDecks=selectedShowcase.map(id=>{const d=(state.decks||[]).find(x=>String(x.id)===id);return d?{id:String(d.id),name:d.name||'Saved Deck',card_count:typeof deckCount==='function'?deckCount(d):20}:null}).filter(Boolean);
 const row={id:uid,display_name:(document.getElementById('pfDisplay')?.value||'').trim().slice(0,40),username:(document.getElementById('pfUser')?.value||'').trim().toLowerCase().replace(/[^a-z0-9_.-]/g,'').slice(0,30)||null,bio:(document.getElementById('pfBio')?.value||'').trim().slice(0,240),favorite_deck_name:(document.getElementById('pfFav')?.value||'').trim().slice(0,80)||null,avatar_url:safeUrl(document.getElementById('pfAvatar')?.value)||null,banner_url:safeUrl(document.getElementById('pfBanner')?.value)||null,showcase_decks:showcaseDecks,featured_badges:selectedBadges,privacy:{...((cloudProfile||{}).privacy||{}),public_profile:publicProfile},updated_at:new Date().toISOString()};
 const {error}=await c.from('profiles').upsert(row,{onConflict:'id'});if(error)return ppcNotice(error.message);cloudProfile={...(cloudProfile||{}),...row};await refreshCompetitiveIdentity();ppcNotice('Competitive profile saved.');profilePage(true)
}
async function ensurePublicClient(){if(ptClient())return ptClient();try{if(typeof initCloud==='function')await initCloud()}catch{}return ptClient()}

async function openPublicProfileByPublicId(publicId){if(!publicId)return;const c=await ensurePublicClient();if(!c)return ppcNotice('Public profiles are temporarily unavailable.');const {data,error}=await c.rpc('get_public_profile_by_public_id',{p_public_profile_id:publicId});if(error)return ppcNotice(error.message);if(!data)return ppcNotice('Public profile not found.');teamWarsState.publicProfile=data;teamWarsState.publicTeam=null;state.page='profile';try{nav?.()}catch{};profilePage(false)}
async function openPublicProfileById(uid){if(!uid)return;const c=await ensurePublicClient();if(!c)return ppcNotice('Public profiles are temporarily unavailable.');const {data,error}=await c.rpc('get_public_profile_by_id',{p_user_id:uid});if(error)return ppcNotice(error.message);if(!data)return ppcNotice('This player keeps their profile private.');teamWarsState.publicProfile=data;teamWarsState.publicTeam=null;state.page='profile';try{nav?.()}catch{};profilePage(false)}
async function openPublicProfile(username){if(!username)return;const c=await ensurePublicClient();if(!c)return ppcNotice('Public profiles are temporarily unavailable.');const {data,error}=await c.rpc('get_public_profile',{p_username:username});if(error)return ppcNotice(error.message);if(!data)return ppcNotice('Public profile not found.');teamWarsState.publicProfile=data;teamWarsState.publicTeam=null;state.page='profile';try{nav?.()}catch{};profilePage(false)}
function closePublicIdentity(){teamWarsState.publicProfile=null;teamWarsState.publicTeam=null;render()}
async function openPublicTeam(id){if(!id)return;const c=await ensurePublicClient();if(!c)return ppcNotice('Public teams are temporarily unavailable.');const {data,error}=await c.rpc('get_public_team',{p_team_id:id});if(error)return ppcNotice(error.message);if(!data)return ppcNotice('Public team not found.');teamWarsState.publicTeam=data;teamWarsState.publicProfile=null;state.page='teamwars';try{nav?.()}catch{};teamWarsPage(false)}
function publicProfileHtml(d){const p=d.profile||{},s=d.stats||{},games=(s.wins||0)+(s.losses||0),wr=games?Math.round((s.wins||0)/games*1000)/10:0,showcase=Array.isArray(p.showcase_decks)?p.showcase_decks:[];return `<div class="publicIdentityPage"><button class="secondary identityBack" onclick="closePublicIdentity()">← Back</button>${profileSearchPanel()}<section class="publicProfileHero" ${safeUrl(p.banner_url)?`style="--profile-banner:url('${esc(safeUrl(p.banner_url))}')"`:''}><div class="profileBannerShade"></div>${avatarHtml(p,'publicAvatar')}<div class="publicIdentityTitle"><span class="eyebrow">PUBLIC PLAYER PROFILE</span><h1>${esc(p.display_name||p.username||'Pocket Player')}</h1><p>${p.username?'@'+esc(p.username)+' • ':''}${esc(p.current_rank||'Rank not shared')}${Number.isFinite(p.current_rp)?` • ${p.current_rp} RP`:''}</p></div>${d.team?`<button class="teamIdentityChip" onclick="openPublicTeam('${d.team.id}')">${d.team.logo_url?logoHtml(d.team,'chipLogo'):''}<span>[${esc(d.team.tag)}] ${esc(d.team.name)}</span></button>`:''}</section><div class="publicStatGrid"><article><span>Battle Record</span><strong>${s.wins||0}-${s.losses||0}</strong><small>${wr}% win rate • ${s.battles||0} tracked</small></article><article><span>Team Wars</span><strong>${s.team_war_wins||0}</strong><small>${s.team_wars||0} completed with team</small></article><article><span>Achievements</span><strong>${(d.badges||[]).length}</strong><small>Verified milestones</small></article><article><span>Team Role</span><strong>${esc(d.team?.role||'Free Agent')}</strong><small>${d.team?`[${esc(d.team.tag)}] ${esc(d.team.name)}`:'No current team'}</small></article></div><div class="profilesOverviewGrid"><section class="panel publicBio"><span class="eyebrow">ABOUT</span><p>${esc(p.bio||'This player has not written a bio yet.')}</p><div class="profileMiniFacts"><div><span>Favorite deck</span><strong>${esc(p.favorite_deck_name||'Not featured')}</strong></div><div><span>Current rank</span><strong>${esc(p.current_rank||'Not shared')}</strong></div></div></section><section class="panel"><span class="eyebrow">TROPHY CABINET</span><h2>Featured achievements</h2>${featuredBadgeCards(p,d.badges||[])}</section></div>${showcase.length?`<section class="panel"><span class="eyebrow">DECK SHOWCASE</span><h2>Featured decks</h2><div class="profileDeckShowcase">${showcase.map(x=>`<article><strong>${esc(x.name||'Featured Deck')}</strong><small>${Number(x.card_count)||20} cards</small></article>`).join('')}</div></section>`:''}<section class="panel"><div class="between"><div><span class="eyebrow">ACHIEVEMENTS</span><h2>Competitive collection</h2></div><span class="pill">${(d.badges||[]).length} earned</span></div>${badgeCards(d.badges)}</section></div>`}


async function profilePage(force=false){
 const root=document.getElementById('app');if(!root)return;
 if(teamWarsState.publicProfile){root.innerHTML=publicProfileHtml(teamWarsState.publicProfile);return}
 if(!ptSigned()){stopRankedRoomPolling();root.innerHTML=`<div class="profilesHub"><section class="profilesWelcome panel"><span class="eyebrow">PROFILES</span><h1>Public competitive profiles</h1><p class="muted">Search competitors, view trophies and achievements, or sign in to manage your own competitive identity.</p><button onclick="openCloudAccountFromCompetitive()">Sign in to manage my profile</button></section>${profileSearchPanel()}</div>`;return}
 startRankedRoomPolling();
 if(force||(!teamWarsState.loading&&!teamWarsState.allTeams.length))await loadProfileTeamData(force);
 const p=cloudProfile||{},matches=state.matches||[],wins=matches.filter(m=>String(m.result).toLowerCase()==='win').length,losses=matches.filter(m=>String(m.result).toLowerCase()==='loss').length,games=wins+losses,wr=games?Math.round(wins/games*1000)/10:0,pub=p.privacy?.public_profile!==false;
 const team=teamWarsState.team, role=teamWarsState.membership?.role||'Free Agent';
 const showcaseIds=Array.isArray(p.showcase_decks)?p.showcase_decks.map(x=>typeof x==='string'?x:x?.id).filter(Boolean).map(String):[];
 const featured=showcaseIds.map(id=>(state.decks||[]).find(d=>String(d.id)===id)).filter(Boolean).slice(0,3);
 root.innerHTML=`<div class="profilesHub">${profileSearchPanel()}
 <section class="publicProfileHero profilesSelfHero" ${safeUrl(p.banner_url)?`style="--profile-banner:url('${esc(safeUrl(p.banner_url))}')"`:''}><div class="profileBannerShade"></div>${avatarHtml(p,'publicAvatar')}<div class="publicIdentityTitle"><span class="eyebrow">PUBLIC PROFILE</span><h1>${esc(p.display_name||state.user||'Pocket Player')}</h1><p>${p.username?'@'+esc(p.username)+' • ':''}${esc(p.current_rank||'Rank not shared')}${Number.isFinite(p.current_rp)?` • ${p.current_rp} RP`:''}</p><div class="row"><span class="pill">${pub?'Public':'Private'}</span>${team?`<button class="teamIdentityChip compact" onclick="openPublicTeam('${team.id}')">[${esc(team.tag)}] ${esc(team.name)}</button>`:''}</div></div><div class="profilesHeroActions"><button class="secondary" onclick="document.getElementById('profileEditPanel')?.showModal()">Edit Profile</button><button class="secondary" onclick="headerNavigate('account')">Account & Cloud</button></div></section>
 <nav class="profilesTabs" aria-label="Profile sections"><button class="active" onclick="profilesShowTab('overview',this)">Overview</button><button onclick="profilesShowTab('achievements',this)">Achievements</button><button onclick="profilesShowTab('decks',this)">Deck Showcase</button></nav>
 <div id="profiles-overview" class="profilesTabPane active"><div class="publicStatGrid profilesStatGrid"><article><span>Battle Record</span><strong>${wins}-${losses}</strong><small>${wr}% win rate • ${games} tracked</small></article><article><span>Rank</span><strong>${esc(p.current_rank||'Not set')}</strong><small>${Number.isFinite(p.current_rp)?p.current_rp+' RP':'Update from Rank'}</small></article><article><span>Achievements</span><strong>${teamWarsState.badges.length}</strong><small>Competitive badges earned</small></article><article><span>Team</span><strong>${esc(team?`[${team.tag}] ${team.name}`:'Free Agent')}</strong><small>${esc(role)}</small></article></div>
 <div class="profilesOverviewGrid"><section class="panel"><span class="eyebrow">ABOUT</span><h2>Player identity</h2><p>${esc(p.bio||'Add a short bio to tell other players about your playstyle and competitive goals.')}</p><div class="profileMiniFacts"><div><span>Favorite deck</span><strong>${esc(p.favorite_deck_name||'Not featured')}</strong></div><div><span>Team role</span><strong>${esc(role)}</strong></div></div></section><section class="panel"><div class="between"><div><span class="eyebrow">TROPHY CABINET</span><h2>Featured achievements</h2></div><button class="textButton" onclick="profilesShowTab('achievements',document.querySelectorAll('.profilesTabs button')[1])">View all</button></div>${featuredBadgeCards(p,teamWarsState.badges)}</section></div></div>
 <div id="profiles-achievements" class="profilesTabPane"><section class="panel"><div class="between"><div><span class="eyebrow">ACHIEVEMENTS</span><h2>Competitive badge collection</h2><p class="muted">Milestones earned from verified Pocket Companion activity.</p></div><button class="secondary" onclick="loadProfileTeamData(true).then(()=>profilePage(false))">Refresh</button></div>${achievementCollectionHtml()}</section></div>
 <div id="profiles-decks" class="profilesTabPane"><section class="panel"><span class="eyebrow">DECK SHOWCASE</span><h2>Featured decks</h2><p class="muted">A quick look at decks you choose to represent your profile. Full deck privacy controls can be expanded later.</p><div class="profileDeckShowcase">${featured.length?featured.map(d=>`<article><strong>${esc(d.name||'Saved Deck')}</strong><small>${typeof deckCount==='function'?deckCount(d):(Array.isArray(d.cards)?d.cards.length:Object.values(d.cards||{}).reduce((a,b)=>a+Number(b||0),0))} cards</small></article>`).join(''):'<div class="identityEmpty"><strong>No featured decks yet</strong><span>Choose up to 3 decks in Edit Profile.</span></div>'}</div></section></div>
 <dialog id="profileEditPanel" class="profileEditDialog"><form method="dialog"><button class="profileDialogClose" aria-label="Close">×</button></form><span class="eyebrow">EDIT PUBLIC PROFILE</span><h2>Profile details</h2><div class="formGrid"><label>Display name<input id="pfDisplay" value="${esc(p.display_name||state.user||'')}"></label><label>Username<input id="pfUser" value="${esc(p.username||'')}" placeholder="unique username"></label><label>Avatar URL<input id="pfAvatar" value="${esc(p.avatar_url||'')}" placeholder="https://…"></label><label>Banner URL<input id="pfBanner" value="${esc(p.banner_url||'')}" placeholder="https://…"></label><label>Favorite deck<input id="pfFav" value="${esc(p.favorite_deck_name||'')}" placeholder="Deck to feature"></label><label class="identityToggle"><input id="pfPublic" type="checkbox" ${pub?'checked':''}><span>Public competitive profile</span></label><label class="span2">Featured decks<select id="pfShowcase" multiple size="${Math.min(6,Math.max(3,(state.decks||[]).length))}">${(state.decks||[]).map(d=>`<option value="${esc(d.id)}" ${showcaseIds.includes(String(d.id))?'selected':''}>${esc(d.name||'Saved Deck')} • ${typeof deckCount==='function'?deckCount(d):''}/20</option>`).join('')}</select><small class="muted">Choose up to 3. Hold Ctrl/Cmd to select multiple.</small></label><label class="span2">Featured achievements<select id="pfFeaturedBadges" multiple size="${Math.min(6,Math.max(3,teamWarsState.badges.length))}">${teamWarsState.badges.map(b=>`<option value="${esc(b.badge_key)}" ${(Array.isArray(p.featured_badges)?p.featured_badges:[]).map(String).includes(String(b.badge_key))?'selected':''}>${esc(b.label)} • ${esc(String(b.tier||'common'))}</option>`).join('')}</select><small class="muted">Choose up to 4 achievements for your Trophy Cabinet.</small></label><label class="span2">Bio<textarea id="pfBio" maxlength="240" rows="4" placeholder="Competitive goals, playstyle, team role…">${esc(p.bio||'')}</textarea></label></div><div class="row"><button onclick="profileSave();document.getElementById('profileEditPanel')?.close()">Save Profile</button></div></dialog>
 </div>`;
}
function profilesShowTab(name,btn){document.querySelectorAll('.profilesTabPane').forEach(x=>x.classList.toggle('active',x.id===`profiles-${name}`));document.querySelectorAll('.profilesTabs button').forEach(x=>x.classList.toggle('active',x===btn));}


async function createTeam(){if(!ptSigned())return ppcNotice('Sign in first.');const name=(document.getElementById('twName')?.value||'').trim(),tag=(document.getElementById('twTag')?.value||'').trim().toUpperCase(),desc=(document.getElementById('twDesc')?.value||'').trim();if(name.length<2||tag.length<2)return ppcNotice('Enter a team name and 2–8 character tag.');const {error}=await ptClient().from('teams').insert({name,tag,description:desc,captain_user_id:ptSession().user.id});if(error)return ppcNotice(error.message);await loadProfileTeamData(true);teamWarsPage(true)}
async function updateTeamIdentity(){const t=teamWarsState.team;if(!t)return;const logo=safeUrl(document.getElementById('twLogo')?.value)||null,description=(document.getElementById('twTeamDesc')?.value||'').trim().slice(0,300);const {error}=await ptClient().from('teams').update({logo_url:logo,description,updated_at:new Date().toISOString()}).eq('id',t.id);if(error)return ppcNotice(error.message);ppcNotice('Team identity updated.');await loadProfileTeamData(true);teamWarsPage(false)}
async function makeInvite(){if(!teamWarsState.team)return;const {data,error}=await ptClient().from('team_invites').insert({team_id:teamWarsState.team.id,created_by:ptSession().user.id}).select('invite_code,expires_at').single();if(error)return ppcNotice(error.message);window.prompt('Share this Team Wars invite code:',data.invite_code)}
async function acceptInvite(){const code=(document.getElementById('twInviteCode')?.value||'').trim();if(!code)return ppcNotice('Enter an invite code.');const {error}=await ptClient().rpc('accept_team_invite',{p_code:code});if(error)return ppcNotice(error.message);await loadProfileTeamData(true);teamWarsPage(true)}
async function scheduleWar(){const opp=document.getElementById('twOpponent')?.value;if(!opp||!teamWarsState.team)return ppcNotice('Choose an opponent team.');const when=document.getElementById('twWhen')?.value||null;const active=teamWarsState.seasons.find(s=>s.status==='active');const {error}=await ptClient().from('team_wars').insert({home_team_id:teamWarsState.team.id,away_team_id:opp,season_id:active?.id||null,scheduled_at:when?new Date(when).toISOString():null,created_by:ptSession().user.id});if(error)return ppcNotice(error.message);await loadProfileTeamData(true);teamWarsPage(true)}
async function openWar(id){const c=ptClient();teamWarsState.selectedWar=teamWarsState.wars.find(w=>w.id===id)||null;const [{data:l},{data:m}]=await Promise.all([c.from('team_war_lineups').select('*').eq('war_id',id).order('slot'),c.from('team_war_matches').select('*').eq('war_id',id).order('sequence_no')]);teamWarsState.lineups=l||[];teamWarsState.matches=m||[];teamWarsPage(false)}
async function saveMyLineup(warId){const w=teamWarsState.wars.find(x=>x.id===warId),t=teamWarsState.team;if(!w||!t)return;const rows=[];for(let i=1;i<=5;i++){const u=document.getElementById(`luUser${i}`)?.value,d1=document.getElementById(`luD1${i}`)?.value,d2=document.getElementById(`luD2${i}`)?.value;if(!u)continue;rows.push({war_id:warId,team_id:t.id,slot:i,user_id:u,deck_1:deckSnapById(d1),deck_2:deckSnapById(d2),losses:0,eliminated:false,active_deck:1})}if(!rows.length)return ppcNotice('Add at least one lineup player.');await ptClient().from('team_war_lineups').delete().eq('war_id',warId).eq('team_id',t.id);const {error}=await ptClient().from('team_war_lineups').insert(rows);if(error)return ppcNotice(error.message);ppcNotice('Lineup saved.');openWar(warId)}
async function recordWar(side){const w=teamWarsState.selectedWar;if(!w)return;const {data,error}=await ptClient().rpc('record_team_war_result',{p_war_id:w.id,p_winner_side:side,p_notes:''});if(error)return ppcNotice(error.message);await refreshCompetitiveIdentity();await loadProfileTeamData(true);await openWar(w.id);ppcNotice(`Match recorded • ${data.home_score}-${data.away_score}`)}
function teamName(id){return teamWarsState.allTeams.find(t=>t.id===id)?.name||'Team'}
function rosterOptions(sel=''){return `<option value="">Choose player…</option>${teamWarsState.members.filter(m=>m.status==='active').map(m=>`<option value="${m.user_id}" ${m.user_id===sel?'selected':''}>${esc(memberLabel(m.user_id))}</option>`).join('')}`}
function warDetailHtml(w){const mine=teamWarsState.lineups.filter(x=>x.team_id===teamWarsState.team.id);return `<section class="panel warConsole"><div class="between"><div><span class="eyebrow">LIVE WAR</span><h2>${esc(teamName(w.home_team_id))} vs ${esc(teamName(w.away_team_id))}</h2></div><span class="pill">${esc(w.status)}</span></div><div class="warScore"><div><span>${esc(teamName(w.home_team_id))}</span><strong>${w.home_score}</strong></div><b>—</b><div><span>${esc(teamName(w.away_team_id))}</span><strong>${w.away_score}</strong></div></div><h3>Your 5-player lineup</h3><div class="lineupEditor">${[1,2,3,4,5].map(i=>{const r=mine.find(x=>x.slot===i);return `<article><b>Slot ${i}</b><select id="luUser${i}">${rosterOptions(r?.user_id)}</select><select id="luD1${i}">${deckOptions(r?.deck_1?.id)}</select><select id="luD2${i}">${deckOptions(r?.deck_2?.id)}</select>${r?`<small>${r.losses} loss${r.losses===1?'':'es'} • ${r.eliminated?'Eliminated':'Deck '+r.active_deck}</small>`:''}</article>`}).join('')}</div><button onclick="saveMyLineup('${w.id}')">Save My 5-Player Lineup</button><div class="warActions"><h3>Record next battle</h3><p class="muted">The backend automatically handles deck switching and player elimination.</p><div class="row"><button onclick="recordWar('home')">Home Win</button><button class="secondary" onclick="recordWar('draw')">Draw</button><button class="danger" onclick="recordWar('away')">Away Win</button></div></div><div class="warHistory"><h3>Battle timeline</h3>${teamWarsState.matches.length?teamWarsState.matches.map(m=>`<div class="warHistoryRow"><span>#${m.sequence_no}</span><strong>${m.winner_side==='draw'?'Draw':esc(m.winner_side)+' win'}</strong><small>${fmtWhen(m.played_at)}</small></div>`).join(''):`<p class="muted">No battles recorded yet.</p>`}</div></section>`}
function publicTeamHtml(d){const t=d.team||{},r=d.record||{},roster=d.roster||[];return `<div class="publicIdentityPage"><button class="secondary identityBack" onclick="closePublicIdentity()">← Back</button><section class="publicTeamHero">${logoHtml(t,'publicTeamLogo')}<div><span class="eyebrow">PUBLIC TEAM PAGE</span><div class="teamTitle"><span>[${esc(t.tag||'TEAM')}]</span><h1>${esc(t.name||'Team')}</h1></div><p>${esc(t.description||'Competitive Team Wars squad')}</p></div><div class="publicTeamRecord"><strong>${r.wins||0}-${r.losses||0}</strong><span>${r.wars||0} wars</span></div></section><section class="panel"><div class="between"><div><span class="eyebrow">ROSTER</span><h2>Competitive roster</h2></div><span class="pill">${roster.length} players</span></div><div class="publicRosterGrid">${roster.map(p=>`<button class="publicRosterCard" onclick="openPublicProfileById('${p.user_id}')">${avatarHtml(p,'rosterAvatar')}<div><strong>${esc(p.display_name||p.username||'Player')}</strong><small>${esc(p.role||'member')}${p.current_rank?' • '+esc(p.current_rank):''}</small></div><span>View →</span></button>`).join('')||'<p class="muted">No public roster entries yet.</p>'}</div></section><section class="panel"><span class="eyebrow">WAR HISTORY</span><h2>Recent Team Wars</h2><div class="warCards">${(d.recent_wars||[]).map(w=>`<div class="warCard publicWar"><span>${esc(w.status)}</span><strong>${esc(teamName(w.home_team_id))} ${w.home_score} — ${w.away_score} ${esc(teamName(w.away_team_id))}</strong><small>${fmtWhen(w.scheduled_at)}</small></div>`).join('')||'<p class="muted">No wars yet.</p>'}</div></section></div>`}
function seasonStandingsHtml(){const active=teamWarsState.seasons.find(s=>s.status==='active');return `<div class="between seasonHeading"><div><span class="eyebrow">${active?'ACTIVE SEASON':'LEAGUE'}</span><h2>${esc(active?.name||'Team Wars Season Standings')}</h2></div>${active?`<span class="pill">${new Date(active.starts_at).toLocaleDateString()} – ${new Date(active.ends_at).toLocaleDateString()}</span>`:''}</div><div class="standingsTable"><div class="standingsHead"><span>#</span><span>Team</span><span>W</span><span>L</span><span>PTS</span></div>${(teamWarsState.seasonStandings||[]).map((s,i)=>`<button class="standingTeamRow" onclick="openPublicTeam('${s.team_id}')"><span>${i+1}</span><strong>${s.logo_url?'<span class="standLogo imageAvatar" style="background-image:url(\''+esc(s.logo_url)+'\')"></span>':''}[${esc(s.tag)}] ${esc(s.team_name)}</strong><span>${s.wins}</span><span>${s.losses}</span><b>${s.points}</b></button>`).join('')||`<p class="muted">Season standings will appear after teams complete wars.</p>`}</div>`}
async function teamWarsPage(force=false){
 const root=document.getElementById('app');if(!root)return;
 if(teamWarsState.publicTeam){root.innerHTML=publicTeamHtml(teamWarsState.publicTeam);return}
 if(teamWarsState.publicProfile){root.innerHTML=publicProfileHtml(teamWarsState.publicProfile);return}
 if(!ptSigned()){stopRankedRoomPolling();root.innerHTML=`<div class="panel emptyState"><span class="eyebrow">TEAM WARS</span><h1>Sign in to compete as a team</h1><p class="muted">Team identity, ranked matchmaking, seasons, rosters, and war history are cloud-backed.</p><button onclick="openCloudAccountFromCompetitive()">Open Account</button></div>`;return}
 startRankedRoomPolling();
 if(force||(!teamWarsState.loading&&!teamWarsState.allTeams.length))await loadProfileTeamData(force);
 if(teamWarsState.error){root.innerHTML=`<div class="dangerBox">${esc(teamWarsState.error)}</div>`;return}
 if(!teamWarsState.team){root.innerHTML=`<div class="teamWarsPage teamWarsV8544"><section class="teamWarsHero compactHero"><div><span class="eyebrow">TEAM WARS</span><h1>Join the competitive team ladder</h1><p>Create a team, join with an invite, apply to a public team, or list yourself as a free agent.</p></div><button class="secondary" onclick="headerNavigate('profile')">My Profile</button></section><div class="teamJoinGrid"><section class="panel"><h2>Create a team</h2><label>Team name<input id="twName" placeholder="Plasma"></label><label>Tag<input id="twTag" maxlength="8" placeholder="PLSM"></label><label>Description<textarea id="twDesc" rows="3" placeholder="What your team competes for"></textarea></label><button onclick="createTeam()">Create Team</button></section><section class="panel"><h2>Join with invite</h2><p class="muted">Ask a captain/admin for a Team Wars invite code.</p><input id="twInviteCode" placeholder="Invite code"><button onclick="acceptInvite()">Join Team</button></section></div><div class="twDiscoverGrid">${applicationBrowserHtml()}${freeAgentHtml()}</div><div class="twLeagueStandalone">${seasonLeagueHtml()}</div></div>`;return}
 const t=teamWarsState.team,staff=['captain','admin'].includes(teamWarsState.membership?.role),recordWins=teamWarsState.wars.filter(w=>w.status==='completed'&&w.winner_team_id===t.id).length,recordLosses=teamWarsState.wars.filter(w=>w.status==='completed'&&w.winner_team_id&&w.winner_team_id!==t.id).length;
 const tabs=[['overview','Overview'],['ranked','Ranked'],['league','League'],['team','Team'],...(staff?[['manage','Manage']]:[])];
 const tabNav=`<nav class="twTabBar">${tabs.map(([id,label])=>`<button class="${teamWarsUi.tab===id?'active':''}" onclick="setTeamWarsTab('${id}')">${label}</button>`).join('')}</nav>`;
 const overview=`<div class="twOverviewGrid"><section class="panel twRosterCard"><div class="between"><div><span class="eyebrow">ROSTER</span><h2>Team Members</h2></div><strong>${teamWarsState.members.length}/${t.max_members}</strong></div><div class="twRosterList">${teamWarsState.members.slice(0,6).map(m=>{const p=memberProfile(m.user_id);return `<button class="rosterRow clickableRoster" onclick="openPublicProfileById('${m.user_id}')">${avatarHtml(p,'miniAvatar')}<div><strong>${esc(memberLabel(m.user_id))}</strong><small>${esc(m.role)}${p.current_rank?' • '+esc(p.current_rank):''}</small></div><span>→</span></button>`}).join('')}</div>${teamWarsState.members.length>6?`<button class="secondary twFullWidth" onclick="setTeamWarsTab('team')">View full roster</button>`:''}</section><section class="panel twSnapshotCard"><span class="eyebrow">TEAM SNAPSHOT</span><div class="twSnapshotStats"><div><strong>${Number(t.rating_points||1500)}</strong><span>Team RP</span></div><div><strong>${recordWins}-${recordLosses}</strong><span>War Record</span></div><div><strong>${teamWarsState.wars.length}</strong><span>Wars</span></div><div><strong>${teamWarsState.members.length}</strong><span>Members</span></div></div><button class="primary twFullWidth" onclick="setTeamWarsTab('ranked')">Queue Ranked Match</button></section></div><section class="panel twRecentWars"><div class="between"><div><span class="eyebrow">RECENT ACTIVITY</span><h2>War History</h2></div><button class="secondary" onclick="setTeamWarsTab('team')">All Wars</button></div><div class="warCards compact">${teamWarsState.wars.slice(0,4).map(w=>`<button class="warCard" onclick="openWar('${w.id}');setTeamWarsTab('team')"><span>${esc(w.status)}</span><strong>${esc(teamName(w.home_team_id))} ${w.home_score} — ${w.away_score} ${esc(teamName(w.away_team_id))}</strong><small>${fmtWhen(w.scheduled_at||w.created_at)}</small></button>`).join('')||`<p class="muted">No wars yet.</p>`}</div></section>`;
 const ranked=`${rankedSeasonHeroHtml()}${rankedQueueHtml()}${rankedLeaderboardHtml()}${rankedHistoryHtml()}${rankedContributorsHtml()}${rankedDisputesHtml()}${rankedBetaQaHtml()}${rankedArchiveHtml()}<section class="panel twRankedInfo"><span class="eyebrow">MATCHMAKING RULES</span><h2>Shared Team RP, season ladder</h2><div class="queueRules"><span>✓ Every season starts teams at 1500 RP</span><span>✓ Win +20 / Loss -20</span><span>✓ No streak bonus</span><span>✓ Same team and same tag can never match</span><span>✓ Private-match code is generated here</span><span>✓ Both players confirm before RP moves</span></div></section>`;
 const team=`<div class="twTeamGrid"><section class="panel"><div class="between"><div><span class="eyebrow">ROSTER</span><h2>Full Team</h2></div><strong>${teamWarsState.members.length}</strong></div>${teamWarsState.members.map(m=>{const p=memberProfile(m.user_id);return `<button class="rosterRow clickableRoster" onclick="openPublicProfileById('${m.user_id}')">${avatarHtml(p,'miniAvatar')}<div><strong>${esc(memberLabel(m.user_id))}</strong><small>${esc(m.role)} • ${esc(m.status)}${p.current_rank?' • '+esc(p.current_rank):''}</small></div><span>Profile →</span></button>`}).join('')}</section><section class="panel"><div class="between"><div><span class="eyebrow">WAR ROOM</span><h2>All Wars</h2></div><span class="pill">${teamWarsState.wars.length}</span></div><div class="warCards">${teamWarsState.wars.length?teamWarsState.wars.map(w=>`<button class="warCard ${teamWarsState.selectedWar?.id===w.id?'active':''}" onclick="openWar('${w.id}')"><span>${esc(w.status)}</span><strong>${esc(teamName(w.home_team_id))} ${w.home_score} — ${w.away_score} ${esc(teamName(w.away_team_id))}</strong><small>${fmtWhen(w.scheduled_at||w.created_at)}</small></button>`).join(''):`<p class="muted">No wars scheduled yet.</p>`}</div></section></div>${teamWarsState.selectedWar?warDetailHtml(teamWarsState.selectedWar):''}`;
 const manage=`<div class="twManageStack"><section class="panel"><div class="between"><div><span class="eyebrow">TEAM SETTINGS</span><h2>Identity & Invitations</h2></div><button onclick="makeInvite()">Create Invite</button></div><div class="twManageGrid"><label>Logo URL<input id="twLogo" value="${esc(t.logo_url||'')}" placeholder="https://…"></label><label>Description<textarea id="twTeamDesc" rows="3">${esc(t.description||'')}</textarea></label></div><button onclick="updateTeamIdentity()">Save Team Identity</button></section><section class="panel"><span class="eyebrow">SCHEDULE</span><h2>Schedule a War</h2><div class="twManageGrid"><select id="twOpponent"><option value="">Opponent team…</option>${teamWarsState.allTeams.filter(x=>x.id!==t.id).map(x=>`<option value="${x.id}">[${esc(x.tag)}] ${esc(x.name)}</option>`).join('')}</select><input id="twWhen" type="datetime-local"></div><button onclick="scheduleWar()">Schedule War</button></section>${rosterManagementHtml()}${teamApplicationHtml()}${freeAgentHtml()}</div>`;
 const content=teamWarsUi.tab==='ranked'?ranked:teamWarsUi.tab==='league'?seasonLeagueHtml():teamWarsUi.tab==='team'?team:teamWarsUi.tab==='manage'?manage:overview;
 root.innerHTML=`<div class="teamWarsPage teamWarsV8544"><section class="teamWarsHero teamIdentityHero compactIdentityHero">${logoHtml(t,'teamHeroLogo')}<div class="teamHeroCopy"><span class="eyebrow">TEAM WARS</span><div class="teamTitle"><span>[${esc(t.tag)}]</span><h1>${esc(t.name)}</h1></div><p>${esc(t.description||'Competitive team')}</p></div><div class="twHeroStats"><div><strong>${Number(t.rating_points||1500)}</strong><span>RP</span></div><div><strong>${recordWins}-${recordLosses}</strong><span>Record</span></div><div><strong>${teamWarsState.members.length}</strong><span>Members</span></div></div><div class="heroButtons"><button class="secondary" onclick="openPublicTeam('${t.id}')">Public Page</button><button class="secondary" onclick="headerNavigate('profile')">Profile</button></div></section>${tabNav}<main class="twTabContent">${content}</main></div>`;
}

