function activeSeason(){return teamWarsState.selectedSeason||teamWarsState.seasons.find(s=>s.status==='active')||teamWarsState.seasons[0]||null}
function seasonTeamEntries(id){return teamWarsState.seasonEntries.filter(x=>x.season_id===id&&x.status==='active')}
