/* V8.60.0 — Team Ranked Completion Foundation */
async function openRankedDispute(matchId){
 const note=(document.getElementById('rankedDisputeNote')?.value||'').trim();
 const {error}=await ptClient().rpc('open_my_team_ranked_dispute',{p_match_id:matchId,p_note:note||null});
 if(error)return ppcNotice(error.message);ppcNotice('Dispute case opened. No RP will move while the result is disputed.');await loadProfileTeamData(true);teamWarsPage(false)
}

async function resolveRankedDispute(disputeId,resolution){
 if(!teamWarsState.rankedStaff)return ppcNotice('Team Ranked staff access required.');
 const note=(document.getElementById(`rankedStaffNote-${disputeId}`)?.value||'').trim();
 const label=resolution==='void'?'void this match with no RP change':resolution==='team_a_win'?'award the win to Team A':'award the win to Team B';
 if(!confirm(`Resolve this dispute and ${label}? This action is recorded in the audit history.`))return;
 const {data,error}=await ptClient().rpc('resolve_team_ranked_dispute',{p_dispute_id:disputeId,p_resolution:resolution,p_note:note||null});
 if(error)return ppcNotice(error.message);
 ppcNotice(data?.rating_changed?`Dispute resolved. Ranked RP was settled by ${Number(data.rating_delta||20)} RP.`:'Dispute resolved. Match voided with no RP change.');
 await loadProfileTeamData(true);teamWarsPage(false)
}

function rankedEvidenceRows(disputeId){return (teamWarsState.rankedEvidence||[]).filter(e=>e.dispute_id===disputeId)}
function rankedEvidenceHtml(d){
 const rows=rankedEvidenceRows(d.id),mine=ptSession()?.user?.id,submitters=[...new Set(rows.map(e=>e.submitted_by))],myRows=rows.filter(e=>e.submitted_by===mine),deadline=d.evidence_deadline_at?fmtWhen(d.evidence_deadline_at):'24 hours after opening',activeMatch=teamWarsState.rankedMatch,isParticipant=activeMatch?.id===d.match_id&&[activeMatch.player_a_id,activeMatch.player_b_id].includes(mine),canUpload=isParticipant&&['open','under_review'].includes(d.status)&&(!d.evidence_deadline_at||new Date(d.evidence_deadline_at)>new Date());
 return `<div class="rankedEvidenceBox"><div class="between"><div><strong>Screenshot Evidence</strong><small>${submitters.length}/2 players submitted • Deadline ${esc(deadline)}</small></div><span class="pill ${submitters.length>=2?'ready':''}">${submitters.length>=2?'Ready for review':'Proof required'}</span></div><div class="rankedEvidenceGrid">${rows.length?rows.map(e=>{const u=teamWarsState.rankedEvidenceUrls.get(e.id);return `<article class="rankedEvidenceCard"><div class="rankedEvidenceThumb">${u?`<a href="${esc(u)}" target="_blank" rel="noopener"><img src="${esc(u)}" alt="Dispute screenshot evidence"></a>`:'<span>Image unavailable</span>'}</div><div><strong>${e.submitted_by===mine?'Your screenshot':'Opponent screenshot'}</strong><small>${esc(e.file_name)} • ${Math.max(1,Math.round(Number(e.file_size||0)/1024))} KB • ${fmtWhen(e.created_at)}</small>${e.note?`<p>${esc(e.note)}</p>`:''}</div></article>`}).join(''):'<div class="identityEmpty"><strong>No screenshots uploaded yet</strong><span>Both players must upload proof before staff can award a winner.</span></div>'}</div>${!teamWarsState.rankedStaff&&canUpload&&myRows.length<3?`<div class="rankedEvidenceUpload"><label>Upload proof screenshot <small>PNG/JPG/WebP • max 5 MB • up to 3 screenshots</small><input id="rankedEvidenceFile-${d.id}" type="file" accept="image/png,image/jpeg,image/webp"></label><input id="rankedEvidenceNote-${d.id}" maxlength="300" placeholder="Optional note: what does this screenshot prove?"><button onclick="uploadRankedDisputeEvidence('${d.id}','${d.match_id}')">Upload Screenshot</button></div>`:''}${!teamWarsState.rankedStaff&&!canUpload&&d.status!=='resolved'?'<div class="dangerBox">The evidence upload deadline has passed. Staff can still void the match if proof is incomplete.</div>':''}</div>`
}
async function uploadRankedDisputeEvidence(disputeId,matchId){
 if(!ptSigned())return ppcNotice('Sign in to upload dispute proof.');
 const input=document.getElementById(`rankedEvidenceFile-${disputeId}`),file=input?.files?.[0],note=(document.getElementById(`rankedEvidenceNote-${disputeId}`)?.value||'').trim();
 if(!file)return ppcNotice('Choose a screenshot first.');
 if(!['image/png','image/jpeg','image/webp'].includes(file.type))return ppcNotice('Use a PNG, JPG, or WebP screenshot.');
 if(file.size>5242880)return ppcNotice('Screenshot must be 5 MB or smaller.');
 const mine=rankedEvidenceRows(disputeId).filter(e=>e.submitted_by===ptSession().user.id);if(mine.length>=3)return ppcNotice('You already uploaded the maximum 3 screenshots for this dispute.');
 const ext=file.type==='image/png'?'png':file.type==='image/webp'?'webp':'jpg',uid=ptSession().user.id,rand=globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`,path=`${uid}/${disputeId}/${rand}.${ext}`,c=ptClient();
 const up=await c.storage.from('team-ranked-evidence').upload(path,file,{cacheControl:'3600',upsert:false,contentType:file.type});if(up.error)return ppcNotice(up.error.message);
 const {error}=await c.from('team_ranked_dispute_evidence').insert({dispute_id:disputeId,match_id:matchId,submitted_by:uid,storage_path:path,file_name:String(file.name||`evidence.${ext}`).slice(0,160),mime_type:file.type,file_size:file.size,note:note.slice(0,300)||null});
 if(error){try{await c.storage.from('team-ranked-evidence').remove([path])}catch{}return ppcNotice(error.message)}
 ppcNotice('Screenshot proof uploaded.');await loadProfileTeamData(true);teamWarsPage(false)
}
async function abandonRankedMatch(matchId){const m=teamWarsState.rankedMatch;if(!m)return;const otherRequested=m.abandon_requested_by&&m.abandon_requested_by!==ptSession()?.user?.id;const reason=otherRequested?'':(prompt('Optional reason for ending this match with no result:','')||'');if(!confirm(otherRequested?'Confirm ending this match with no RP change?':'Request to end this match with no result? Your opponent must also confirm.'))return;const {data,error}=await ptClient().rpc('abandon_team_ranked_match',{p_match_id:matchId,p_reason:reason||null});if(error)return ppcNotice(error.message);ppcNotice(data?.status==='abandoned'?'Match ended with no RP change.':'No-result request sent. Waiting for the other player.');await loadProfileTeamData(true);teamWarsPage(false)}
async function refreshRankedLifecycle(){const {data,error}=await ptClient().rpc('cleanup_team_ranked_lifecycle');if(error)return ppcNotice(error.message);ppcNotice(`Lifecycle check complete: ${Number(data?.stale_queues_removed||0)} stale queue(s), ${Number(data?.matches_expired||0)} expired match(es).`);await loadProfileTeamData(false);teamWarsPage(false)}
const rankedQaSteps=['Two different signed-in accounts are on two different teams/tags','Both players queue and enter the same Ranked Match Room/private code','Refresh or sign back in and confirm the active Match Room recovers','Same-team, same-tag, double-queue, and second-active-match protections remain blocked','Reciprocal opposite reports settle exactly +20 / -20 RP and close the room','Conflicting reports freeze RP and automatically lead players to dispute review','Both disputed players upload screenshot evidence on the website','Staff reviews screenshots and resolves winner or void with audit history','Queue expiry, match timeout, and two-party no-result flow behave correctly','Leaderboard, ranked history, contributors, and season data reflect the final result'];
function rankedQaState(){try{return JSON.parse(localStorage.getItem('ppcRankedQa8604')||localStorage.getItem('ppcRankedQa8603')||localStorage.getItem('ppcRankedQa8602')||'{}')}catch{return {}}}
function setRankedQaStep(i,v){const x=rankedQaState();x[i]=!!v;localStorage.setItem('ppcRankedQa8604',JSON.stringify(x));const badge=document.getElementById('rankedQaProgress');if(badge){const done=rankedQaSteps.filter((_,n)=>x[n]).length;badge.textContent=`${done}/${rankedQaSteps.length}${done===rankedQaSteps.length?' • PASS':''}`;badge.classList.toggle('ready',done===rankedQaSteps.length)}}
function resetRankedQa(){if(!window.confirm('Reset the V8.60.4 Team Ranked beta QA checklist?'))return;localStorage.removeItem('ppcRankedQa8604');localStorage.removeItem('ppcRankedQa8603');teamWarsPage(false)}
function rankedBetaQaHtml(){if(!teamWarsState.rankedStaff)return '';const q=rankedQaState(),done=rankedQaSteps.filter((_,i)=>q[i]).length,pass=done===rankedQaSteps.length;return `<section class="panel rankedQaPanel ${pass?'qaPassed':''}"><div class="between"><div><span class="eyebrow">V8.60.4 FINAL TEAM RANKED QA</span><h2>${pass?'Beta checklist passed':'Controlled Two-Team Test Flow'}</h2></div><span id="rankedQaProgress" class="pill ${pass?'ready':''}">${done}/${rankedQaSteps.length}${pass?' • PASS':''}</span></div><p class="muted">Run this with two separate tester accounts on the hosted beta. V8.60 should only be marked complete after every item is observed successfully.</p><div class="rankedQaChecklist">${rankedQaSteps.map((x,i)=>`<label><input type="checkbox" ${q[i]?'checked':''} onchange="setRankedQaStep(${i},this.checked)"><span>${esc(x)}</span></label>`).join('')}</div><div class="row wrap"><button class="secondary" onclick="refreshRankedLifecycle()">Run Lifecycle Cleanup Check</button><button class="secondary" onclick="resetRankedQa()">Reset QA Checklist</button></div>${pass?'<div class="infoBox rankedQaPass"><strong>V8.60 Team Ranked QA gate passed on this browser.</strong><span>Record any hosted-beta issues before declaring the milestone complete.</span></div>':''}</section>`}

