function rankedDisputesHtml(){const rows=teamWarsState.rankedDisputes||[],m=teamWarsState.rankedMatch,staff=teamWarsState.rankedStaff;return `<section class="panel rankedDisputeCenter"><div class="between"><div><span class="eyebrow">${staff?'STAFF DISPUTE QUEUE':'DISPUTE CENTER'}</span><h2>${staff?'Team Ranked Resolution Console':'Ranked Result Review'}</h2></div><span class="pill">${rows.filter(x=>['open','under_review'].includes(x.status)).length} open</span></div>${staff?'<div class="infoBox">A disputed winner cannot be awarded until both actual players upload screenshot proof. Staff can void a match if evidence is missing, unclear, or the deadline passes. Every decision is audit logged.</div>':''}${m?.status==='disputed'&&!rows.some(x=>x.match_id===m.id)?`<div class="rankedDisputeOpen"><p>Conflicting reports froze this match automatically. Open the case, then both players must upload screenshot proof on this website.</p><textarea id="rankedDisputeNote" rows="3" maxlength="500" placeholder="Optional context for staff review — do not include passwords or private account credentials."></textarea><button onclick="openRankedDispute('${m.id}')">Open Dispute & Upload Proof</button></div>`:''}<div class="rankedDisputeList">${rows.length?rows.map(d=>{const submitters=[...new Set(rankedEvidenceRows(d.id).map(e=>e.submitted_by))],ready=submitters.length>=2;return `<article class="${staff?'staffCase':''}"><div><strong>${esc(String(d.status).replace('_',' '))}</strong><small>${fmtWhen(d.created_at)} • Match ${esc(shortId(d.match_id))}</small></div><span class="pill">${esc(d.resolution||'No RP change')}</span>${d.player_note?`<p>${esc(d.player_note)}</p>`:''}${d.resolution_note?`<small>${esc(d.resolution_note)}</small>`:''}${rankedEvidenceHtml(d)}${staff&&d.status!=='resolved'?`<div class="rankedStaffResolve"><textarea id="rankedStaffNote-${d.id}" rows="2" maxlength="1000" placeholder="Staff resolution note (recommended)"></textarea><div class="row wrap"><button ${ready?'':'disabled title="Both players must upload screenshot proof first"'} onclick="resolveRankedDispute('${d.id}','team_a_win')">Team A Won</button><button ${ready?'':'disabled title="Both players must upload screenshot proof first"'} onclick="resolveRankedDispute('${d.id}','team_b_win')">Team B Won</button><button class="danger" onclick="resolveRankedDispute('${d.id}','void')">Void Match</button></div>${ready?'<small>Both players submitted proof. Winner resolution is unlocked.</small>':'<small>Winner buttons stay locked until both players submit at least one screenshot.</small>'}</div>`:''}${rankedDisputeEventsHtml(d.id)}</article>`}).join(''):`<div class="identityEmpty"><strong>No dispute cases</strong><span>Conflicting reports will appear here without changing Team RP.</span></div>`}</div></section>`}
