/* V8.54.3 — Ranked Team Queue */
function rankedOpponentTeam(m){if(!m||!teamWarsState.team)return null;const id=m.team_a_id===teamWarsState.team.id?m.team_b_id:m.team_a_id;return teamWarsState.allTeams.find(t=>t.id===id)||null}
function rankedMyReport(m){if(!m)return null;return m.player_a_id===ptSession()?.user?.id?m.player_a_report:m.player_b_report}
async function copyRankedCode(code){const value=String(code||'');try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(value);else throw new Error('clipboard unavailable');ppcNotice('Private match code copied.')}catch{window.prompt('Copy this private match code:',value)}}
function rankedPlayerName(id){const p=teamWarsState.rankedPlayerProfiles?.get(id);return p?.display_name||p?.username||`Player ${shortId(id)}`}
function rankedMatchStage(m){if(!m)return 0;if(m.status==='disputed')return 4;if(m.status==='reported')return 3;if(m.status==='completed')return 5;return 2}
function rankedMatchTimelineHtml(m){const stage=rankedMatchStage(m),steps=[['Matched',1],['Playing',2],['Result Reported',3],[m?.status==='disputed'?'Disputed':'Verified',4],['Completed',5]];return `<div class="rankedMatchTimeline">${steps.map(([label,n])=>`<div class="${stage>=n?'done':''} ${stage===n?'current':''}"><span>${stage>n?'✓':n}</span><small>${esc(label)}</small></div>`).join('')}</div>`}
function rankedQueueHtml(){
 if(!teamWarsState.team)return '';const t=teamWarsState.team,q=teamWarsState.rankedQueue,m=teamWarsState.rankedMatch,opp=rankedOpponentTeam(m),uid=ptSession()?.user?.id;
 if(m&&['matched','reported','disputed'].includes(m.status)){const mine=rankedMyReport(m),codeLive=!m.code_expires_at||new Date(m.code_expires_at)>new Date(),otherAbandon=m.abandon_requested_by&&m.abandon_requested_by!==uid,myPlayer=m.player_a_id===uid?m.player_a_id:m.player_b_id,oppPlayer=m.player_a_id===uid?m.player_b_id:m.player_a_id;return `<section class="panel rankedQueuePanel matchFound rankedMatchRoom"><div class="between"><div><span class="eyebrow">RANKED MATCH ROOM</span><h2>${m.status==='disputed'?'Result Disputed':'Active Team Ranked Match'}</h2><p class="muted">Match ${esc(shortId(m.id))} • reconnect-safe</p></div><span class="pill">${Number(t.rating_points||1500)} RP</span></div>${rankedMatchTimelineHtml(m)}<div class="rankedMatchup"><div><strong>[${esc(t.tag)}] ${esc(t.name)}</strong><small>${esc(rankedPlayerName(myPlayer))} • ${m.team_a_id===t.id?m.team_a_rating_before:m.team_b_rating_before} RP</small></div><b>VS</b><div><strong>${opp?`[${esc(opp.tag)}] ${esc(opp.name)}`:'Opponent Team'}</strong><small>${esc(rankedPlayerName(oppPlayer))} • ${m.team_a_id===t.id?m.team_b_rating_before:m.team_a_rating_before} RP</small></div></div>${codeLive?`<div class="privateMatchCode"><span>PRIVATE MATCH CODE</span><strong>${esc(m.private_code)}</strong><button class="secondary" onclick="copyRankedCode('${esc(m.private_code)}')">Copy Code</button></div>`:'<div class="dangerBox">This private-match code has expired. Refresh lifecycle status to close the match safely.</div>'}<div class="rankedRoomInstructions"><strong>Play this match in Pokémon TCG Pocket</strong><span>Private Match → both players enter the same code → finish the game → return here to report the result.</span><small>Match/code expires ${esc(fmtWhen(m.match_expires_at||m.code_expires_at))}. Refreshing or signing back in will recover this active room.</small></div>${m.status==='disputed'?`<div class="dangerBox"><strong>RP is frozen.</strong> Conflicting reports moved this match to the Dispute Center. Both players must upload screenshot proof before staff can award a winner.</div>`:mine?`<div class="identityEmpty"><strong>You reported: ${mine==='win'?'WIN':'LOSS'}</strong><span>Waiting for ${esc(rankedPlayerName(oppPlayer))} to submit the reciprocal result.</span></div>`:`<div class="rankedReportBox"><strong>Report only after the Pocket match is finished.</strong><div class="row rankedResultButtons"><button onclick="reportRankedResult('${m.id}','win')">Report Win</button><button class="secondary" onclick="reportRankedResult('${m.id}','loss')">Report Loss</button></div></div>`}${m.status!=='disputed'&&!mine?`<div class="rankedNoResult"><button class="secondary" onclick="abandonRankedMatch('${m.id}')">${otherAbandon?'Confirm End Match — No RP':'Request No-Result / Abandon'}</button>${m.abandon_requested_by?`<small>${otherAbandon?'Opponent requested to end with no result.':'Waiting for opponent to confirm no-result request.'}</small>`:'<small>Ending with no result requires both players to agree. No RP changes.</small>'}</div>`:''}<div class="row wrap rankedRoomFooter"><button class="secondary" onclick="refreshRankedLifecycle()">Refresh Match Status</button>${m.status==='disputed'?`<button onclick="document.querySelector('.rankedDisputeCenter')?.scrollIntoView({behavior:'smooth'})">Open Dispute Center</button>`:''}</div></section>`}
 if(q?.status==='queued')return `<section class="panel rankedQueuePanel searching"><div class="between"><div><span class="eyebrow">TEAM WARS RANKED</span><h2>Searching for an opponent…</h2></div><span class="pill">${Number(t.rating_points||1500)} RP</span></div><div class="queuePulse"><span></span><strong>Matchmaking active</strong></div><p class="muted">Queue expires ${esc(fmtWhen(q.expires_at))}. We search for another team near your Team RP. Same team/tag [${esc(t.tag)}] remains hard-blocked.</p><div class="row wrap"><button class="secondary" onclick="leaveRankedQueue()">Cancel Queue</button><button class="secondary" onclick="refreshRankedLifecycle()">Refresh</button></div></section>`;
 return `<section class="panel rankedQueuePanel"><div class="between"><div><span class="eyebrow">TEAM WARS RANKED</span><h2>Queue for a rated match</h2></div><strong class="rankedBigRating">${Number(t.rating_points||1500)} RP</strong></div><p>Every confirmed result moves the team's shared rating by <b>20 RP</b>. There are no streak bonuses.</p><div class="queueRules"><span>✓ Opponent must be on another team</span><span>✓ Same tag [${esc(t.tag)}] is hard-blocked</span><span>✓ One active ranked match per player</span><span>✓ Queue expires after 10 minutes</span><span>✓ Private code/match expires after 30 minutes</span><span>✓ Both players confirm before RP moves</span><span>✓ Disputes require screenshots from both players</span></div><button class="rankedQueueButton" onclick="joinRankedQueue()">Find Ranked Match</button></section>`
}
async function joinRankedQueue(){if(!ptSigned()||!teamWarsState.team)return ppcNotice('Join a team first.');const {data,error}=await ptClient().rpc('join_team_ranked_queue');if(error)return ppcNotice(error.message);if(data?.status==='matched')ppcNotice(`Match found — code ${data.private_code}`);else ppcNotice(`Searching. Same-tag opponents are blocked.`);await loadProfileTeamData(false);teamWarsPage(false)}
