async function reportRankedResult(id,result){const label=result==='win'?'WIN':'LOSS';if(!window.confirm(`Report ${label}? Only submit the result after the Pokémon TCG Pocket match is finished. A conflicting report will freeze RP and require screenshot evidence.`))return;const {data,error}=await ptClient().rpc('report_team_ranked_result',{p_match_id:id,p_result:result});if(error)return ppcNotice(error.message);if(data?.status==='completed')ppcNotice(`Result confirmed. Team rating changed by ${data.rating_delta} RP.`);else if(data?.status==='disputed'){try{await ptClient().rpc('open_my_team_ranked_dispute',{p_match_id:id,p_note:'Conflicting player reports — screenshot evidence required.'})}catch{}ppcNotice('Result disputed. No Team RP changed. Both players must upload screenshot proof.');}else ppcNotice('Result submitted. Waiting for opponent confirmation.');await loadProfileTeamData(true);teamWarsPage(false)}

